{
  "title": "CSCI-549 Orientation Companion",
  "learningObjectives": [
    "Identify the flexible, faculty-defined nature of the CSCI-549 seminar structure and its cluster affiliations.",
    "Apply core programming concepts (algorithms, data structures, correctness) to evaluate potential course topics.",
    "Construct a preliminary syllabus outline using the provided planning framework and assessment criteria."
  ],
  "beats": [
    {
      "title": "Course Scope and Flexibility",
      "claim": "CSCI-549 examines current topics in Languages and Tools to allow faculty to pilot potential new undergraduate offerings, with specific details determined by the proposing faculty.",
      "example": "A faculty member might propose a seminar on 'Secure Coding Practices' or 'Natural Language Processing Pipelines' as a pilot course.",
      "visualDirection": "Display the official catalog description text in a centered, high-contrast box with a subtle gradient background to emphasize its authoritative yet flexible nature.",
      "sourceIds": ["rit-csci-549"]
    },
    {
      "title": "Cluster Affiliations",
      "claim": "Specific instances of CSCI-549 will be identified as belonging to the Languages and Tools cluster, the Security cluster, or both clusters.",
      "example": "A course focusing on 'Python for Security Analysis' would be tagged with both clusters, while a course on 'Graph Algorithms' would belong solely to the Languages and Tools cluster.",
      "visualDirection": "Render a Venn diagram with two overlapping circles labeled 'Languages and Tools' and 'Security'; place a third, smaller circle labeled 'Both' at the intersection to visually represent the dual-affiliation possibility.",
      "sourceIds": ["rit-csci-549"]
    },
    {
      "title": "Foundational Programming Concepts",
      "claim": "Programming begins with precise problem statements, input/output examples, and algorithms written independently of syntax, utilizing variables, expressions, and control structures.",
      "example": "Before writing code, one defines a problem like 'Sort a list of integers' and outlines an algorithm using variables for the list and a loop (control structure) to iterate.",
      "visualDirection": "Show a split-screen: left side displays a plain-text problem statement and pseudocode; right side shows a blank code editor window ready for syntax-specific implementation.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Data Structures and Representation",
      "claim": "Lists represent ordered sequences, stacks use last-in first-out access, queues use first-in first-out access, and trees represent hierarchy, all of which are essential for solving ",
      "example": "A queue data structure is appropriate for modeling a print job spooler where the first job submitted is the first to be processed.",
      "visualDirection": "Animate a simple queue: boxes labeled 'A', 'B', 'C' enter from the left, and 'A' exits from the right, with arrows indicating the FIFO flow.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Functions and Decomposition",
      "claim": "Functions decompose a solution into named operations with parameters and results, reducing the number of interacting concerns through abstraction.",
      "example": "A function named 'calculate_average' takes a list of numbers as a parameter and returns a single float value, isolating the math logic from the rest of the program.",
      "visualDirection": "Illustrate a block diagram where a large 'Main Program' block is broken down into smaller, labeled blocks representing individual functions, connected by arrows showing data flow.",
      "sourceIds": ["opendsa-programming-foundations", "python-language-reference"]
    },
    {
      "title": "Recursion and Base Cases",
      "claim": "Recursion solves a problem through smaller instances and requires a base case to terminate the process, preventing infinite loops.",
      "example": "Calculating the factorial of 5 involves recursively calling the function for 4, 3, 2, and 1, with the base case defined as factorial(0) = 1.",
      "visualDirection": "Draw a nested set of brackets or a tree diagram where each level represents a recursive call, clearly marking the bottom-most node as the 'Base Case'.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Python Language Semantics",
      "claim": "The Python language reference specifies lexical analysis, data model behavior, execution, and module import semantics, where names are bound to objects within namespaces.",
      "example": "When a script imports a module, Python searches for it and binds the module object to a name in the current namespace, allowing subsequent code to access its functions.",
      "visualDirection": "Present a flowchart starting with 'Import Statement', branching to 'Search Path', then to 'Module Object', and finally to 'Namespace Binding', with icons representing each step.",
      "sourceIds": ["python-language-reference"]
    },
    {
      "title": "Correctness and Testing",
      "claim": "Correctness arguments, tests, tracing, and debugging compare intended behavior with observable results, including boundary and error cases.",
      "example": "A test suite for a sorting function must include not only sorted lists but also empty lists, single-element lists, and lists with duplicate values to verify robustness.",
      "visualDirection": "Show a side-by-side comparison: the left panel displays the 'Intended Behavior' (expected output), and the right panel shows the 'Actual Output' with a highlighted discrepancy indicating a bug.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Debugging and Exception Handling",
      "claim": "Exceptions interrupt normal control flow until a matching handler processes them, and debugging separates syntax, runtime, and logical failures.",
      "example": "If a division by zero occurs, Python raises a ZeroDivisionError; a try-except block catches this exception, preventing the program from crashing and allowing graceful recovery.",
      "visualDirection": "Render a code snippet with a `try` block containing a risky operation and an `except` block below it, with a visual indicator (like a red flag) appearing when the exception is triggered.",
      "sourceIds": ["python-language-reference"]
    },
    {
      "title": "Planning and Evaluation Checklist",
      "claim": "Faculty must determine prerequisites, format, learning outcomes, and assessment methods for any pilot course, ensuring alignment with the Languages and Tools or Security cluster.",
      "example": "A checklist for a new 'Intro to Python Security' course includes verifying that students have basic programming knowledge, defining weekly lecture topics, and setting up a final project assessment.",
      "visualDirection": "Display a clean, bulleted checklist graphic with checkboxes next to items like 'Define Prerequisites', 'Set Learning Outcomes', 'Choose Format', and 'Plan Assessments', styled to look like a printable handout.",
      "sourceIds": ["rit-csci-549"]
    }
  ]
}
